import assert from 'node:assert/strict';
import { createGenerationHarness } from './bsh-product/test/helpers/generation-harness.mjs';
import { regionFixture } from './bsh-product/test/helpers/region-fixture.mjs';

async function open(data) {
  const harness = createGenerationHarness(42);
  harness.render();
  harness.guardRandom();
  harness.setWindow({alert: message => { throw new Error(message); }, matchMedia: () => ({matches:false})});
  harness.injectFunction('readTextFile', async file => file.text);
  await harness.render().handleImportJson({target:{files:[{text:JSON.stringify(data)}], value:''}});
  harness.render();
  return harness;
}

const save = harness => JSON.parse(JSON.stringify(harness.render().createSaveData()));
const fixture = regionFixture('classic');
const regionB = fixture.map.regions[1];
regionB.pointsOfInterest = [{q:3,r:1}];
regionB.pointOfInterestKinds = {'3,1':'village'};
const ownerA = {kind:'poi',regionId:1,hexKey:'2,0'};
const ownerB = {kind:'poi',regionId:2,hexKey:'3,1'};
const seed = save(await open(fixture));
seed.map.editorNames = {'poi:1:2,0':{ru:'Завод',en:'Factory'},'poi:2:3,1':{ru:'Завод',en:'Factory'}};
const harness = await open(seed);
assert.equal(harness.render().mutateTag(ownerA,'mb.feature'),true);
const authored = save(harness);
const reopened = save(await open(authored));
const tagsAt = (data, owner) => data.map.tags.instances.filter(record => record.owner.kind===owner.kind && record.owner.regionId===owner.regionId && record.owner.hexKey===owner.hexKey);
assert.equal(tagsAt(reopened,ownerA).length,1);
assert.equal(tagsAt(reopened,ownerB).length,0);
assert.deepEqual(reopened.map.editorNames,seed.map.editorNames);
assert.deepEqual(reopened.map.tags,authored.map.tags);

const hypothetical = structuredClone(reopened);
hypothetical.map.areaSalvageByPoi = {'poi:1:2,0':{techLevel:2,initialSupply:3}};
const reexported = save(await open(hypothetical));
assert.equal(Object.hasOwn(reexported.map,'areaSalvageByPoi'),false);
assert.deepEqual(reexported.map.tags,reopened.map.tags);
const result = {owners:[ownerA,ownerB], names:reopened.map.editorNames, tagCountA:tagsAt(reopened,ownerA).length, tagCountB:tagsAt(reopened,ownerB).length, identicalTagsAfterReopen:true, inputSupplyWasSynthetic:true, importedSyntheticFieldReexported:Object.hasOwn(reexported.map,'areaSalvageByPoi')};
console.log(JSON.stringify(result));
